	('02d93a50-6805-448e-bf11-c30a9c7ac7d8', '64e9e2eb-1bfe-4c87-9835-4d86ac06cd64', '44fe4378-c1e4-40f1-881c-a08d331caf2b', 7, 10, NULL, 'SITE IS NOT HANDED OVER UNTIL SNAGS ARE CLOSED', 'Joint inspection of the premises, preparation of a\nwritten snag list, and rectification of every recorded\nitem followed by deep cleaning and a final\nwalkthrough for sign-off.', 0, 0, 5, '2026-11-24 12:10:26', '2026-11-24 12:10:26', NULL),
	('1da8a77a-8000-4061-8772-e6c21563931c', '64e9e2eb-1bfe-4c87-9835-4d86ac06cd64', 'eac2327f-0fab-4cf7-a4ef-5072d8f03657', NULL, NULL, NULL, NULL, 'Handing over of the completed premises along with\nkeys, warranty cards, appliance manuals, as-built\nservice drawings and vendor contacts, together with\na walkthrough of operation and maintenance\nrequirements.', 0, 0, 6, '2026-11-24 12:10:26', '2026-11-24 12:10:26', NULL),
