INSERT INTO `project_brief_site_restrictions` (`id`, `project_brief_id`, `sort_order`, `type`, `details`, `created_at`, `updated_at`) VALUES
	('72bbfa64-3f17-4a79-8dd9-5959682bd60e', '1f4ee6a1-4d55-435e-935e-a6ad1641144f', 0, 'societyRwaPermittedWorkTimings', '10am-6pm', '2026-10-30 11:51:35', '2026-10-30 11:51:35'),
	('9a982370-49f7-4a38-ad6e-4904150da78e', '52982cc4-38a2-445d-be35-c5b31716a9a8', 2, 'neighbourSensitivities', 'Avoid excessive drilling, hammering and other high-noise activities during early mornings and evenings.\n\n\n\nInform neighbouring residents at least 48 hours before major noisy activities.\n\n\n\nMaintain cleanliness in shared corridors, staircases and lift areas.\n\n\n\nPrevent dust migration into neighbouring residences through appropriate protective coverings.\n\n\n\nEnsure construction workers do not obstruct visitor parking or common access.\n\n\n\nAvoid loud music, shouting and unnecessary movement in residential common areas.\n\n\n\nCoordinate heavy material deliveries to minimize traffic congestion.\n\n\n\nAddress neighbour complaints promptly through the designated site supervisor.', '2026-11-19 14:25:11', '2026-11-19 14:25:11'),
	('a1a0ba59-b1ce-41dd-8813-570b9bad32cc', 'f82104f8-3477-4530-9e29-3b0604dee9bd', 0, 'societyRwaPermittedWorkTimings', '10:00 Am to 6:00 Pm', '2026-11-23 12:04:00', '2026-11-23 12:04:00'),
	('d9508664-94eb-47d6-8096-43bd30ab67df', '52982cc4-38a2-445d-be35-c5b31716a9a8', 1, 'nocOrSecurityDepositRequired', 'Written RWA permission and renovation NOC required before commencement.\n\n\n\nEstimated refundable renovation security deposit: ₹50,000.\n\n\n\nContractor registration and submission of worker identification documents.\n\n\n\nSubmission of contractor details, scope of work and tentative execution schedule.\n\n\n\nElectrical and plumbing modification details to be submitted for approval where applicable.\n\n\n\nDebris disposal and common-area protection undertaking required.\n\n\n\nLift protection deposit or additional charges may apply.\n\n\n\nFinal inspection and clearance required before security deposit refund.', '2026-11-19 14:25:11', '2026-11-19 14:25:11'),
	('f4708098-a3b3-41de-94ab-9eec7257cab2', '52982cc4-38a2-445d-be35-c5b31716a9a8', 0, 'societyRwaPermittedWorkTimings', 'Activity	Permitted Timings\nGeneral Interior Work	Monday–Saturday, 9:00 AM – 6:00 PM\nDrilling & Heavy Noise Work	Monday–Friday, 10:00 AM – 1:00 PM and 3:00 PM – 5:00 PM\nMaterial Loading / Unloading	9:00 AM – 5:00 PM\nSunday / Public Holidays	No noisy construction activities\nEmergency Maintenance	Subject to prior security and RWA approval', '2026-11-19 14:25:11', '2026-11-19 14:25:11');
