INSERT INTO `scope_of_work` (`id`, `project_id`, `scope_summary`, `specific_exclusions`, `notes`, `project_mode`, `version`, `status`, `prepared_by`, `reviewed_by`, `accepted_at`, `accepted_by`, `client_signature_name`, `client_signature_date`, `created_at`, `updated_at`, `deleted_at`, `total_area_sqft`, `document_date`, `authorised_signatory_name`, `authorised_signatory_date`) VALUES
	('dfdceb59-53b2-4b04-94cf-e2bf76eeb419', '38dd0c32-6e6c-4222-b61d-4f8710630984', '•	LIVING ROOM\n•	KITCHEN\n•	MASTER BEDROOM\n•	MASTER WASHROOM\n•	KIDS BEDROOM\n•	PARENTS BEDROOM \n•	COMMON WASHROOM\n•	LOBBY AREA\n•	BALCONY', 'Refurbished \n* Mandir \nLIVING area\n* No side table in living area only center table \n\nLOBBY\n* Ceiling/ wall spot light wall frames above console table and crockery unit ( depth 1\'6")\n* Additional storage in balcony wall for vacuum etc depth \nKITCHEN \n* No demolition work in kitchen column \n* Only microwave or air frier or mixer etc\n* Kitchen island size to be changed to 5\'\n* Storage in Island doors and shutter \n* Island side wall switch board \nMaster bedroom \n* Add additional low height storage join with vanity \n Kids bedroom \n* Replace side table to wardrobe \n* Cut in wardrobe \nParents room \n* Colour change according to vastu \n Common washroom \n* Sliding partition \n  Master washroom \n* Vanity location to be confirmed from vastu consultant', '', 'DESIGN_BUILD', 1, 'APPROVED', NULL, NULL, NULL, NULL, NULL, NULL, '2026-10-30 12:04:03', '2026-11-21 13:00:38', '2026-11-21 13:00:38', NULL, NULL, NULL, NULL),
	('feae4bd7-164c-4fa9-bbe4-5a27f626aa5e', 'c4a41869-a229-4bbb-bc90-83bcfe6f68f1', '- Entrance Foyer & Main Lobby\n- Formal Living Room\n- Family Lounge\n- Dining Area\n- Modular Kitchen & Utility\n- Master Bedroom with Walk-in Wardrobe\n- 2 Guest Bedrooms\n- Kids’ Bedroom\n- Attached Bathrooms\n- Powder Room\n- Internal Staircase & Upper Landing\n- Balcony & Terrace Seating\n- Wardrobes, Storage & Custom Furniture\n- Lighting, Ceiling & Interior Finishes', '- Structural modifications and major civil construction\n- External façade redesign and elevation work\n- Landscaping and outdoor garden development\n- Boundary wall, gate and driveway construction\n- Swimming pool and water-feature installations\n- Home automation and security system integration\n- HVAC and centralized air-conditioning systems\n- Solar panel and renewable energy installations\n- External plumbing and drainage infrastructure\n- Loose décor accessories and artwork procurement (unless separately commissioned)', NULL, 'BUILD_ONLY', 2, 'APPROVED', NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-15 06:48:13', '2026-11-23 11:24:29', '2026-11-23 11:24:29', NULL, NULL, NULL, NULL);
INSERT INTO `settings` (`id`, `key`, `value`, `updated_by`, `updated_at`) VALUES
	('4689e689-8ce3-4326-bd73-2d8176ae1b03', 'proposal_next_steps.6725b123-5893-454d-9e7a-7d14fbaf1fc1', '{"steps": [{"id": "review-proposal", "done": false, "title": "Review this proposal", "detail": "Take a week. Mark anything unclear. We will walk it through with you."}, {"id": "confirm-scope", "done": false, "title": "Confirm the scope", "detail": "Tick the engagement and optional items. We revise the BOQ against your ticks."}, {"id": "freeze-cost", "done": false, "title": "Freeze cost at Gate 02", "detail": "BOQ priced line by line and signed. The estimate becomes a firm number."}, {"id": "sign-agreement", "done": false, "title": "Sign the Agreement", "detail": "Scope of Work, Payment Schedule, Plan of Action issued together for signature."}, {"id": "release-m1", "done": false, "title": "Release M1 and mobilise", "detail": "15% booking and mobilisation. Site team on the ground within five days."}], "checklist": [{"id": "signed-agreement", "done": false, "label": "Signed Scope of Work and Agreement"}, {"id": "booking-payment", "done": false, "label": "Booking and mobilisation payment"}, {"id": "society-permission", "done": false, "label": "Society permission for work and material lift"}, {"id": "site-access", "done": false, "label": "Access, keys and a point of contact at site"}, {"id": "water-power", "done": false, "label": "Water and power connection at the unit"}, {"id": "client-material", "done": false, "label": "Any client-supplied material schedule"}]}', NULL, '2026-10-09 04:20:37'),
	('51d7db8d-148e-460a-9fc0-25ebeffee437', 'terms', '{"default_terms": ""}', NULL, '2026-06-30 09:30:51');
